	function getDefaultBlocksForCategory(category) {
		if (category === 'purchase') return defaultPurchaseBlocks();
		if (category === 'service') return defaultServiceBlocks();
		return defaultLeaseBlocks();
	}

	function mockWordBlocks(fileName, category) {
		var cat = category || 'lease';
		var name = fileName || 'Word';
		if (cat === 'lease' && (/V26\.5|现代18吨|数智中心版/i.test(name) || /商用车租赁合同/.test(name))) {
			return JSON.parse(JSON.stringify(v265LeaseBlocks()));
		}
		var base = getDefaultBlocksForCategory(cat);
		base[0].content = base[0].content + '（导入自 ' + name + '）';
		return base;
	}

