	function parseVersionNo(versionNo) {
		var m = String(versionNo || '').match(/^[vV](\d+)\.(\d{1,2})$/);
		if (!m) return null;
		return { major: parseInt(m[1], 10), minor: parseInt(m[2], 10) };
	}

	function formatVersionNo(major, minor) {
		return 'v' + major + '.' + String(minor).padStart(2, '0');
	}

	function formatNowTime() {
		return '2026-06-09 ' + new Date().toTimeString().slice(0, 5);
	}

	function generateNextVersionNo(category) {
		var list = templates.filter(function (t) {
			return t.category === category && t.status === 'published' && t.versionNo;
		});
		var maxMajor = 0;
		var maxMinor = -1;
		list.forEach(function (t) {
			var parsed = parseVersionNo(t.versionNo);
			if (!parsed) return;
			if (parsed.major > maxMajor || (parsed.major === maxMajor && parsed.minor > maxMinor)) {
				maxMajor = parsed.major;
				maxMinor = parsed.minor;
			}
		});
		if (maxMinor < 0) return 'v1.00';
		if (maxMinor >= 99) return formatVersionNo(maxMajor + 1, 0);
		return formatVersionNo(maxMajor, maxMinor + 1);
	}

	function stripFileExtension(name) {
		return String(name || '').replace(/\.[^.]+$/, '');
	}

	function buildAutoVersionName(category, versionNo, importFileName) {
		var imported = stripFileExtension(importFileName);
		if (imported) return imported;
		var catOpt = CATEGORY_OPTIONS.find(function (c) { return c.value === category; });
		if (!versionNo) return (catOpt ? catOpt.label : '合同模板') + ' 草稿';
		return (catOpt ? catOpt.label : '合同模板') + ' ' + versionNo;
	}

