	function handleSaveTemplate(publish) {
		var docHtml = (formDocumentHtmlState[0] || '').trim();
		if (!docHtml) {
			message.warning('请先导入 Word 并解析到编辑器');
			return;
		}
		var blocks = documentToBlocks(docHtml);
		var now = formatNowTime();
		var importName = lastImportFileNameState[0] || '';

		if (editorMode === 'create') {
			if (publish) {
				var versionNo = generateNextVersionNo(categoryFilter);
				var newItem = {
					id: 't' + Date.now(),
					category: categoryFilter,
					versionNo: versionNo,
					versionName: buildAutoVersionName(categoryFilter, versionNo, importName),
					status: 'published',
					isDefault: false,
					blocks: JSON.parse(JSON.stringify(blocks)),
					creator: CURRENT_USER,
					createTime: now,
					updater: CURRENT_USER,
					updateTime: now,
					remark: ''
				};
				setTemplates(function (prev) { return prev.concat([newItem]); });
				message.success('已发布，版本号 ' + versionNo);
			} else {
				var draftItem = {
					id: 't' + Date.now(),
					category: categoryFilter,
					versionNo: null,
					versionName: buildAutoVersionName(categoryFilter, null, importName),
					status: 'draft',
					isDefault: false,
					blocks: JSON.parse(JSON.stringify(blocks)),
					creator: CURRENT_USER,
					createTime: now,
					updater: CURRENT_USER,
					updateTime: now,
					remark: ''
				};
				setTemplates(function (prev) { return prev.concat([draftItem]); });
				message.success('草稿已保存（未生成版本号）');
			}
		} else if (editingRecord) {
			if (publish) {
				if (editingRecord.status === 'published') {
					var cat = editingRecord.category;
					var nextVersionNo = generateNextVersionNo(cat);
					var newVersion = {
						id: 't' + Date.now(),
						category: cat,
						versionNo: nextVersionNo,
						versionName: buildAutoVersionName(cat, nextVersionNo, importName || editingRecord.versionName),
						status: 'published',
						isDefault: false,
						blocks: JSON.parse(JSON.stringify(blocks)),
						creator: CURRENT_USER,
						createTime: now,
						updater: CURRENT_USER,
						updateTime: now,
						remark: editingRecord.remark || ''
					};
					setTemplates(function (prev) { return prev.concat([newVersion]); });
					message.success('已发布新版本 ' + nextVersionNo + '，原版本保留可回滚');
				} else {
					var publishVersionNo = generateNextVersionNo(editingRecord.category);
					setTemplates(function (prev) {
						return prev.map(function (t) {
							if (t.id !== editingRecord.id) return t;
							return Object.assign({}, t, {
								versionNo: publishVersionNo,
								versionName: buildAutoVersionName(t.category, publishVersionNo, importName || t.versionName),
								status: 'published',
								blocks: JSON.parse(JSON.stringify(blocks)),
								updater: CURRENT_USER,
								updateTime: now
							});
						});
					});
					message.success('已发布，版本号 ' + publishVersionNo);
				}
			} else {
				setTemplates(function (prev) {
					return prev.map(function (t) {
						if (t.id !== editingRecord.id) return t;
						var patch = {
							blocks: JSON.parse(JSON.stringify(blocks)),
							updater: CURRENT_USER,
							updateTime: now,
							status: 'draft',
							versionNo: null
						};
						if (importName) {
							patch.versionName = buildAutoVersionName(t.category, null, importName);
						}
						return Object.assign({}, t, patch);
					});
				});
				message.success('草稿已保存（未生成版本号）');
			}
		}
		backToList();
	}

